int parse_git_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_PKT_ERROR_SHORT_BUFFER;
    }

    int len = 0;
    for (int i = 0; i < 4; ++i) {
        char ch = line[i];
        if (!isdigit(ch)) {
            return GIT_PKT_ERROR_INVALID_HEADER;
        }
        len = len * 16 + (ch - '0');
    }

    if (len == 0) {
        *out = line + 4;
        return GIT_PKT_OK;
    }

    if (bufflen < (size_t)(4 + len)) {
        return GIT_PKT_ERROR_SHORT_BUFFER;
    }

    if (line[4] == 'A' && line[5] == 'C') {
        int result = handle_ack_packet(head, line + 4, len);
        if (result != GIT_PKT_OK)
            return result;
    } else if (line[4] == 'S') {
        int result = handle_sideband_packet(head, line + 4, len);
        if (result != GIT_PKT_OK)
            return result;
    } else if (line[4] == 'D') {
        int result = handle_data_packet(head, line + 4, len);
        if (result != GIT_PKT_OK)
            return result;
    } else {
        int result = handle_unknown_packet(head, line + 4, len);
        if (result != GIT_PKT_OK)
            return result;
    }

    *out = line + 4 + len;
    return GIT_PKT_OK;
}

int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    const char *ptr = line;
    size_t len;

    if (bufflen < 5)
        return -1;

    if (memcmp(ptr, "ACK ", 4) == 0) {
        return parse_ack_pkt(head, ptr + 4, out, bufflen - 4);
    } else if (memcmp(ptr, "NAK", 3) == 0) {
        *out = ptr + 4;
        return 0;
    } else if (memcmp(ptr, "SIDE ", 5) == 0) {
        return parse_sideband_pkt(head, ptr + 5, out, bufflen - 5);
    } else if (sscanf(ptr, "%zu", &len) == 1) {
        if (len > bufflen - 4)
            return -1;

        git_pkt *pkt = malloc(sizeof(git_pkt));
        if (!pkt)
            return -1;

        pkt->data = malloc(len + 1);
        if (!pkt->data) {
            free(pkt);
            return -1;
        }

        memcpy(pkt->data, ptr + 4, len);
        ((char *)pkt->data)[len] = '\0';
        pkt->next = *head;
        *head = pkt;

        *out = ptr + 4 + len;
        return 0;
    }

    return -1;
}

int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    const char *start = line;
    const char *end = line + bufflen;

    if (bufflen < 4)
        return GIT_PKT_ERROR_SHORT;

    if (!strncmp(line, "0000", 4)) {
        *out = line + 4;
        return GIT_PKT_EOF;
    }

    if (!strncmp(line, "000a", 4)) {
        *out = line + 4;
        return GIT_PKT_FLUSH;
    }

    if (bufflen < 4)
        return GIT_PKT_ERROR_SHORT;

    size_t pkt_len = strtol(line, NULL, 16);
    if (pkt_len < 4 || pkt_len > bufflen) {
        return GIT_PKT_ERROR_INVALID;
    }

    if (pkt_len == 0) {
        *out = line + 4;
        return GIT_PKT_EOF;
    }

    if (pkt_len == 4) {
        *out = line + 4;
        return GIT_PKT_FLUSH;
    }

    if (pkt_len + 4 > bufflen)
        return GIT_PKT_ERROR_SHORT;

    if (start[4] == 'A') {
        return handle_sideband_pkt(head, line, out, bufflen);
    } else {
        git_pkt *pkt = git_pkt_new(pkt_len - 4);
        memcpy(pkt->data, line + 4, pkt_len - 4);
        pkt->len = pkt_len - 4;
        pkt->next = *head;
        *head = pkt;
        *out = line + pkt_len;
        return GIT_PKT_OK;
    }
}

int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return -1; // Not enough data to parse a packet line
    }

    int len;
    if (sscanf(line, "%4s", (char *)&len) != 1) {
        return -1; // Failed to parse packet length
    }

    if (len == 0) {
        *out = line + 4;
        return 0;
    }

    if (bufflen < 4 + len) {
        return -1; // Buffer does not contain a complete packet
    }

    // Determine packet type and handle accordingly
    if (strncmp(line + 4, "DATA", 4) == 0) {
        // Handle data packet
        git_pkt *pkt = (git_pkt *)malloc(sizeof(git_pkt));
        if (!pkt) {
            return -1; // Memory allocation failed
        }
        pkt->data = (char *)malloc(len - 4);
        if (!pkt->data) {
            free(pkt);
            return -1; // Memory allocation failed
        }
        memcpy(pkt->data, line + 8, len - 4);
        pkt->size = len - 4;
        pkt->next = *head;
        *head = pkt;
        *out = line + 4 + len;
        return 0;
    } else if (strncmp(line + 4, "SIDB", 4) == 0) {
        // Handle sideband packet
