        if (!pkt) {
            return -1; // Memory allocation failed
        }
        pkt->data = (char *)malloc(len - 4);
        if (!pkt->data) {
            free(pkt);
            return -1; // Memory allocation failed
        }
        memcpy(pkt->data, line + 8, len - 4);
        pkt->size = len - 4;
        pkt->next = *head;
        *head = pkt;
        *out = line + 4 + len;
        return 0;
    } else if (strncmp(line + 4, "ACK ", 4) == 0) {
        // Handle ACK packet
        git_pkt *pkt = (git_pkt *)malloc(sizeof(git_pkt));
        if (!pkt) {
            return -1; // Memory allocation failed
        }
        pkt->data = (char *)malloc(len - 4);
        if (!pkt->data) {
            free(pkt);
            return -1; // Memory allocation failed
        }
        memcpy(pkt->data, line + 8, len - 4);
        pkt->size = len - 4;
        pkt->next = *head;
        *head = pkt;
        *out = line + 4 + len;
        return 0;
