        *out = line + 4;
        return 0;
    }

    if (memcmp(line, "0001", 4) == 0) {
        *out = line + 4;
        return 0;
    }

    if (sscanf(line, "%04" SCNxSIZE_T "%n", &len, &len) != 1)
        return -1;

